import 'package:flutter/material.dart';import '../data/app_store.dart';import '../theme/operon_theme.dart';
class NotesScreen extends StatefulWidget{final AppStore store;const NotesScreen({super.key,required this.store});@override State<NotesScreen> createState()=>_S();}
class _S extends State<NotesScreen>{@override Widget build(BuildContext c){final items=[...widget.store.notes]..sort((a,b)=>a.pinned==b.pinned?b.createdAt.compareTo(a.createdAt):(a.pinned?-1:1));return Scaffold(appBar:AppBar(title:const Text('Operator notes')),body:items.isEmpty?const Center(child:Text('No notes yet')):ListView(children:items.map((n)=>Card(child:ListTile(leading:Icon(n.pinned?Icons.push_pin:Icons.note_alt_outlined,color:OperonTheme.teal),title:Text(n.title),subtitle:Text((n.equipmentTag??'General')+'\n'+n.body),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v){if(v=='pin')widget.store.toggleNotePin(n);if(v=='done')widget.store.resolveNote(n);setState((){});},itemBuilder:(_)=>[const PopupMenuItem(value:'pin',child:Text('Pin / unpin')),if(!n.resolved)const PopupMenuItem(value:'done',child:Text('Resolve'))])))).toList()),floatingActionButton:FloatingActionButton(onPressed:_add,child:const Icon(Icons.add)));}
void _add(){final title=TextEditingController(),body=TextEditingController(),tag=TextEditingController();showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Operator note'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Title')),TextField(controller:tag,decoration:const InputDecoration(labelText:'Equipment TAG')),TextField(controller:body,maxLines:4,decoration:const InputDecoration(labelText:'Note'))]),actions:[FilledButton(onPressed:(){widget.store.addNote(title.text,body.text,tag:tag.text.trim().isEmpty?null:tag.text.trim().toUpperCase());Navigator.pop(c);setState((){});},child:const Text('Save'))]));}}
